//! Complete system/mount/ship dynamic read publication, independent of scene UI.
use crate::{battle::Ordnance,gravity_world as g,lifecycle::{self,Spec},scene_system_read::{self as read,Reader},ship_effects as e,ship_state::ShipState,state::{Body,Handle},system_owner as so,world_owner};
use std::collections::BTreeMap;
#[derive(Clone)]pub struct Propulsion{pub slots:Vec<Option<Handle>>,pub reserves:[f64;3]}
#[derive(Clone)]pub struct Meta{pub ship:Handle,pub tactical_count:usize,pub module_slot:Option<String>,pub propulsion:Option<Propulsion>}
#[derive(Clone)]struct Pending{ship:Handle,tactical_count:usize,label:usize,units:Vec<u16>,slots:usize,propulsion:Option<Propulsion>}
#[derive(Clone,Default)]pub struct Owned{pub ships:Vec<Meta>,pub projectile_ids:Vec<(u32,f64)>,expected:Option<usize>,pending:Option<Pending>}
fn int(n:f64)->Result<u32,u32>{if n.is_finite()&&n>=0.0&&n<=u32::MAX as f64&&n.fract()==0.0{Ok(n as u32)}else{Err(2)}}
fn flag(n:f64)->Result<bool,u32>{match n{0.0=>Ok(false),1.0=>Ok(true),_=>Err(2)}}
impl Meta{pub fn empty(ship:Handle)->Self{Self{ship,tactical_count:0,module_slot:None,propulsion:None}}pub fn valid(&self)->bool{self.ship.generation>0&&self.tactical_count<=64&&self.module_slot.as_ref().is_none_or(|s|!s.is_empty()&&s.encode_utf16().count()<=4096)&&self.propulsion.as_ref().is_none_or(|p|p.slots.len()<=128&&p.reserves.iter().all(|v|v.is_finite()))}}
impl Owned{
    pub fn get(&self,h:Handle)->Result<&Meta,u32>{self.ships.iter().find(|s|s.ship==h).ok_or(8)}
    pub fn admit(&mut self,m:Meta)->Result<(),u32>{if self.expected.is_some()||self.pending.is_some()||!m.valid()||self.ships.iter().any(|s|s.ship==m.ship){return Err(8);}self.ships.push(m);Ok(())}
    pub fn validate(&self,b:&[Body])->Result<(),u32>{if self.expected.is_some()||self.pending.is_some()||self.ships.len()!=b.len(){return Err(8);}for(i,m)in self.ships.iter().enumerate(){if !m.valid()||self.ships[..i].iter().any(|p|p.ship==m.ship){return Err(8);}let s=read::ship(b,m.ship)?;if s.systems.iter().filter(|s|!s.defense).count()!=m.tactical_count.max(1){return Err(8);}
        if let Some(p)=&m.propulsion{for h in p.slots.iter().flatten(){if read::ship(b,*h)?.world.as_ref().ok_or(8u32)?.parent!=Some(m.ship){return Err(8);}}}}
        for(i,(serial,id))in self.projectile_ids.iter().enumerate(){if *serial==0||!id.is_finite()||self.projectile_ids[..i].iter().any(|(s,_)|s==serial){return Err(8);}}Ok(())}
    fn finish_actor(&mut self)->Result<(),u32>{let Some(p)=&self.pending else{return Ok(());};if p.units.len()!=p.label||p.propulsion.as_ref().map_or(0,|p|p.slots.len())!=p.slots{return Err(8);}let p=self.pending.take().unwrap();let label=if p.label>0{Some(String::from_utf16(&p.units).map_err(|_|2u32)?)}else{None};let m=Meta{ship:p.ship,tactical_count:p.tactical_count,module_slot:label,propulsion:p.propulsion};if !m.valid(){return Err(8);}self.ships.push(m);Ok(())}
    pub fn apply(&mut self,tag:u32,v:&[f64],b:&[Body],own:usize)->Result<(),u32>{if v.len()!=22||v.iter().any(|v|!v.is_finite()){return Err(2);}let h=b.get(own).ok_or(4u32)?.handle;match tag{
        189=>{if v[1..].iter().any(|v|*v!=0.0)||self.expected.is_some()||!self.ships.is_empty()||self.pending.is_some(){return Err(8);}let count=int(v[0])?as usize;if count!=b.len(){return Err(8);}self.expected=Some(count);},
        190=>{if v[8..].iter().any(|v|*v!=0.0){return Err(2);}self.finish_actor()?;let count=self.expected.ok_or(8u32)?;if self.ships.len()>=count||int(v[0])?as usize!=self.ships.len()||self.ships.iter().any(|m|m.ship==h){return Err(8);}let label=int(v[1])?as usize;let has=flag(v[2])?;let slots=int(v[3])?as usize;let tactical_count=int(v[7])?as usize;if label>4096||slots>128||tactical_count>64||!has&&(slots!=0||v[4..7].iter().any(|v|*v!=0.0)){return Err(2);}
            self.pending=Some(Pending{ship:h,tactical_count,label,units:Vec::new(),slots,propulsion:if has{Some(Propulsion{slots:Vec::new(),reserves:[v[4],v[5],v[6]]})}else{None}});},
        191=>{let p=self.pending.as_mut().ok_or(8u32)?;let count=int(v[1])?as usize;if count==0||count>20||p.ship!=h||int(v[0])?as usize!=p.units.len()||p.units.len()+count>p.label||v[2+count..].iter().any(|v|*v!=0.0){return Err(8);}for n in &v[2..2+count]{let n=int(*n)?;if n>65535{return Err(2);}p.units.push(n as u16);}},
        192=>{if v[4..].iter().any(|v|*v!=0.0){return Err(2);}let p=self.pending.as_mut().ok_or(8u32)?;let prop=p.propulsion.as_mut().ok_or(8u32)?;if p.ship!=h||int(v[0])?as usize!=prop.slots.len()||prop.slots.len()>=p.slots{return Err(8);}let present=flag(v[1])?;let slot=if present{let h=Handle{slot:int(v[2])?,generation:int(v[3])?};read::ship(b,h)?;Some(h)}else if v[2]==0.0&&v[3]==0.0{None}else{return Err(2)};prop.slots.push(slot);},
        193=>{if v.iter().any(|v|*v!=0.0){return Err(2);}self.finish_actor()?;if self.expected.take()!=Some(self.ships.len()){return Err(8);}self.validate(b)?;},_=>return Err(2)}Ok(())}
    /// Call at the complete-step publication barrier, before ephemeral retired
    /// projectiles are cleared. Historical hit/release IDs stay exact thereafter.
    pub fn capture_ordnance(&mut self,o:&Ordnance,w:&world_owner::Owned)->Result<(),u32>{for p in o.projectiles.iter().chain(&w.retired_projectiles){let serial=int(p.serial)?;if serial==0||!p.id.is_finite(){return Err(8);}if let Some((_,id))=self.projectile_ids.iter().find(|(s,_)|*s==serial){if *id!=p.id{return Err(8);}}else{self.projectile_ids.push((serial,p.id));}}Ok(())}
}
fn bool_word(b:bool)->f64{b as u32 as f64}
fn string(o:&mut Vec<f64>,s:&str){let v:Vec<_>=s.encode_utf16().collect();o.push(v.len()as f64);o.extend(v.into_iter().map(|v|v as f64));}
fn opt_string(o:&mut Vec<f64>,s:Option<&str>){o.push(bool_word(s.is_some()));if let Some(s)=s{string(o,s);}}
fn optional(o:&mut Vec<f64>,v:Option<f64>){o.push(bool_word(v.is_some()));if let Some(v)=v{o.push(v);}}
fn opt_bool(o:&mut Vec<f64>,v:Option<bool>){optional(o,v.map(bool_word));}
fn record(o:&mut Vec<f64>,n:&mut usize,tag:u32,v:Vec<f64>){o.extend([tag as f64,v.len()as f64]);o.extend(v);*n+=1;}
fn stable(world:&world_owner::Owned,h:Handle)->Result<&str,u32>{Ok(&world.flight.as_ref().ok_or(8u32)?.owner.ship(crate::tactical_ai::Identity{handle:h.slot,generation:h.generation}).map_err(crate::flight_runtime::error)?.stable_id)}
fn target(o:&mut Vec<f64>,t:g::Target,meta:&Owned,w:&world_owner::Owned,ordnance:&Ordnance)->Result<(),u32>{let kind=match t.kind{g::BodyKind::Ship=>0,g::BodyKind::Projectile=>1,g::BodyKind::Asteroid=>2,g::BodyKind::Hulk=>3};o.push(kind as f64);
    if t.kind==g::BodyKind::Ship{string(o,stable(w,Handle{slot:t.identity.slot,generation:t.identity.generation})?);}else if t.kind==g::BodyKind::Projectile{if t.identity.generation!=1{return Err(4);}let serial=t.identity.slot;
        let id=meta.projectile_ids.iter().find(|(s,_)|*s==serial).map(|(_,id)|*id).or_else(||ordnance.projectiles.iter().chain(&w.retired_projectiles).find(|p|p.serial==serial as f64).map(|p|p.id)).ok_or(8u32)?;o.push(id);
    }else{let id=w.gravity.as_ref().ok_or(8u32)?.environments.iter().find(|(k,_,id)|*k==t.kind&&*id==t.identity).ok_or(8u32)?.1;o.push(id);}Ok(())}
fn opt_target(o:&mut Vec<f64>,t:Option<g::Target>,m:&Owned,w:&world_owner::Owned,ordnance:&Ordnance)->Result<(),u32>{o.push(bool_word(t.is_some()));if let Some(t)=t{target(o,t,m,w,ordnance)?;}Ok(())}
fn field(o:&mut Vec<f64>,f:&g::Field,m:&Owned,w:&world_owner::Owned,ordnance:&Ordnance)->Result<(),u32>{o.push(match f.kind{g::FieldKind::Well=>0.0,g::FieldKind::Repulsor=>1.0,g::FieldKind::Collapse=>2.0});optional(o,f.serial);optional(o,f.polarity.map(|n|n as f64));opt_bool(o,f.cursor);optional(o,f.linger);o.extend(f.position);o.extend([f.age,f.radius,f.ship_budget,f.projectile_budget]);optional(o,f.duration);optional(o,f.environment_budget);opt_bool(o,f.collapsed);
    o.push(f.ship_hits.len()as f64);for h in &f.ship_hits{string(o,stable(w,Handle{slot:h.slot,generation:h.generation})?);}o.push(f.projectile_hits.len()as f64);for h in &f.projectile_hits{let mut v=Vec::new();target(&mut v,g::Target{kind:g::BodyKind::Projectile,identity:*h},m,w,ordnance)?;o.push(v[1]);}
    o.push(bool_word(f.environment_hits.is_some()));if let Some(hits)=&f.environment_hits{o.push(hits.len()as f64);for t in hits{let mut v=Vec::new();target(&mut v,*t,m,w,ordnance)?;let key=format!("{}:{}",if t.kind==g::BodyKind::Asteroid{"ASTEROID"}else{"HULK"},crate::gravity_owner::number_key(v[1]));string(o,&key);}}
    o.push(bool_word(f.releases.is_some()));if let Some(releases)=&f.releases{o.push(releases.len()as f64);for t in releases{target(o,*t,m,w,ordnance)?;}}Ok(())}
fn usable(s:&ShipState)->bool{read::live(s)&&!s.flux.venting&&!s.flux.overloaded&&s.control_flags()&64==0&&s.weapons.as_ref().is_some_and(|w|w.mounts.iter().enumerate().any(|(i,m)|m.data[1]==1.0&&m.data[17]!=0.0&&s.components[i].data[7]==0.0))}
fn online(reader:&Reader<'_>,h:Handle,life:&lifecycle::System)->Result<bool,u32>{Ok(reader.owner(h)?.online()&&!life.disabled)}
fn seal_status(m:&Owned,b:&[Body],h:Handle)->Result<Option<String>,u32>{let parts=crate::scene_control::assembly(b,read::root(b,h)?)?.into_iter().filter(|h|read::ship(b,*h).ok().and_then(|s|s.world.as_ref()).is_some_and(|w|w.bulkheads.is_some())).collect::<Vec<_>>();if parts.is_empty(){return Ok(None);}let available=|h:Handle|->Result<bool,u32>{Ok(read::live(read::ship(b,h)?)&&read::ship(b,h)?.world.as_ref().ok_or(8u32)?.parent.map_or(Ok(true),|p|Ok::<bool,u32>(read::live(read::ship(b,p)?)))?)};
    let mut active=Vec::new();let mut reserve=0;let mut waiting=None;for h in &parts{let s=read::ship(b,*h)?;let seal=s.world.as_ref().unwrap().bulkheads.as_ref().unwrap();if available(*h)?{if seal.remaining>0.0{active.push((*h,seal.remaining));}if !seal.used{reserve+=1;if waiting.is_none()&&s.armor.as_ref().ok_or(8u32)?.data[14]<=s.armor.as_ref().unwrap().data[13]*0.4{waiting=Some(*h);}}}}
    let label=|h|->Result<&str,u32>{Ok(m.get(h)?.module_slot.as_deref().unwrap_or("核心"))};Ok(Some(if let Some((h,t))=active.first(){format!("封舱 {} {}s{} · 储备{}/{}",label(*h)?,read::fixed(*t,1),if active.len()>1{format!(" 等{}舱",active.len())}else{String::new()},reserve,parts.len())}else if let Some(h)=waiting{format!("{}待封舱：需25%空余载荷且非排散/过载",label(h)?)}else{format!("封舱储备 {}/{}",reserve,parts.len())}))}
fn propulsion_status(m:&Owned,b:&[Body],w:&world_owner::Owned,h:Handle)->Result<Option<String>,u32>{if m.get(h)?.propulsion.is_none(){return Ok(None);}let p=crate::motion_owner::sample_propulsion(Some(w),b,h)?.ok_or(8u32)?;
    if p.level>=1.0{return Ok(None);}let pct=|i:usize|crate::gravity_owner::number_key((p.factors[i]*100.0+0.5).floor());Ok(Some(format!("动力 {}/{} · 航速{}% 加速{}% 转向{}%",p.online,p.total,pct(0),pct(1),pct(2))))}
fn hyperion_status(reader:&Reader<'_>,h:Handle)->Result<String,u32>{let s=reader.ship(h)?;let world=s.world.as_ref().ok_or(8u32)?;let Some(core)=s.systems.iter().find(|s|world.metas.get(&s.id).is_some_and(|m|m.kind==e::Kind::Yamato))else{return Ok("反应堆核心未装配".into());};if world.flags&so::REACTOR==0{return Ok("旗舰反应堆未装配".into());}
    let mut text=format!("反应堆 {}/{} · 大和{} / 跃迁75{}",crate::gravity_owner::number_key(core.charges),crate::gravity_owner::number_key(reader.specs[&core.spec].max_charges),if world.flags&so::FOCUS!=0{45}else{60},if world.flags&so::FOCUS!=0{" · 聚能/跃迁预热2.4s"}else{""});
    if let Some(r)=&world.repair{let repair=if !reader.owner(h)?.online()||reader.owner(h)?.phased{"抢修暂停".into()}else{let reason=match r.reason{e::RepairReason::Waiting=>"脱战等待",e::RepairReason::Exhausted=>"材料耗尽",e::RepairReason::Ceiling=>"已达80%上限",e::RepairReason::NoReserve=>"储备不足",e::RepairReason::Working=>"修复中"};
        let wait=if r.reason==e::RepairReason::Waiting{format!(" {}s",read::fixed((6.0-r.quiet.min(s.shield.as_ref().ok_or(8u32)?.data[28])).max(0.0),1))}else{String::new()};format!("抢修{}{} · 材料余{}%船体",reason,wait,read::fixed((100.0*(0.2-r.used/s.armor.as_ref().ok_or(8u32)?.data[13])).max(0.0),1))};text.push_str(" | ");text.push_str(&repair);}
    for life in &s.systems{let m=&world.metas[&life.id];if m.kind==e::Kind::Jump&&life.state==lifecycle::COOLDOWN&&m.jump.visual.is_some_and(|v|v.origin.is_some())&&online(reader,h,life)?{let t=(life.cooldown_timer-(reader.specs[&life.spec].cooldown-6.0).max(0.0)).max(0.0);if t>0.0{text.push_str(&format!(" | 跃迁突击 {}s · 火力↑ 载荷成本↑",read::fixed(t,1)));}break;}}Ok(text)}
fn status(m:&Owned,reader:&Reader<'_>,h:Handle,life:&lifecycle::System,kind:e::Kind,gravity:Option<&crate::gravity_owner::SystemMeta>)->Result<(Option<String>,Option<String>),u32>{let s=reader.ship(h)?;let world=s.world.as_ref().ok_or(8u32)?;let mut passive=None;
    let text=match kind{
        e::Kind::Eclipse=>if life.active{Some(format!("日蚀：能量伤害 +{}% · 护盾/散热削弱",crate::gravity_owner::number_key(((0.25+(s.flux.percent()/0.75).min(1.0)*0.75)*life.effect*100.0+0.5).floor())))}else{None},
        e::Kind::Edict=>{let mut p=Vec::new();if let Some(v)=seal_status(m,reader.bodies,h)?{p.push(v);}if let Some(v)=propulsion_status(m,reader.bodies,reader.world,h)?{p.push(v);}if !p.is_empty(){passive=Some(p.join(" · "));}
            let slot=&world.metas[&life.id];let pos=reader.bodies[reader.row(h)?].motion;let side=if life.active{slot.input.map_or(0,|i|e::broadside(i.point,i.origin,i.facing))}else{e::broadside(world.aim,[pos[0],pos[1]],pos[4])};if side==0{Some(if life.active{"敕令中止 · 退出中"}else{"准星选舷：左舷 / 右舷"}.into())}else{let mut count=0;for child in &world.children{let part=reader.ship(*child)?;let w=part.world.as_ref().ok_or(8u32)?;if w.parent==Some(h)&&w.side==side&&usable(part){count+=1;}}
                let name=if side<0{"左舷"}else{"右舷"};Some(if life.active{format!("{}敕令 · {}/3炮廊 · 射速+{}% · 对舷减速",name,count,crate::gravity_owner::number_key(((if online(reader,h,life)?{0.75}else{0.0})*life.effect*100.0+0.5).floor()))}else{format!("准星：{} · {}/3炮廊可用",name,count)})}},
        e::Kind::Yamato|e::Kind::Jump=>{passive=Some(hyperion_status(reader,h)?);if kind==e::Kind::Yamato{match life.state{lifecycle::IN=>Some("大和炮蓄能 · 转向锁定".into()),lifecycle::ACTIVE=>Some("大和炮发射".into()),_=>None}}else if life.state==lifecycle::IN{Some("跃迁引擎预热 · 落点已锁定".into())}else{None}},
        e::Kind::ArkForge|e::Kind::ArkBarrier|e::Kind::ArkRepair=>{if let Some(core)=s.systems.iter().find(|s|world.metas[&s.id].kind==e::Kind::ArkForge){passive=Some(format!("太阳能 {}/{} · 火力40 / 屏障35 / 重构50{}{}",crate::gravity_owner::number_key(core.charges.floor()),crate::gravity_owner::number_key(reader.specs[&core.spec].max_charges),if reader.owner(h)?.engineering_online{""}else{" · 工程段失效：机动/充能降低"},if world.flags&so::CORONA!=0{" · 日冕耦合：回能×0.7"}else{""}));}else{passive=Some(String::new());}None},
        e::Kind::RocAttitude=>if life.state==lifecycle::ACTIVE{Some(format!("惯性急转 · {}s",read::fixed(life.active_timer,2)))}else{None},
        e::Kind::RocFire=>{let text=if !read::live(s){"局部火控离线".into()}else{match life.state{lifecycle::IN=>format!("护航 → 压制 · 重分配 {}s",read::fixed(life.active_timer,2)),lifecycle::OUT=>format!("压制 → 护航 · 重分配 {}s",read::fixed(life.active_timer,2)),lifecycle::ACTIVE=>"压制 · 近防20发/s / 轴炮3s · 弹速+25% / 耗散减半".into(),_=>"护航 · 近防拦截优先 / 正常耗散".into()}};passive=Some(text.clone());Some(text)},
        e::Kind::Zhefeng=>match life.state{lifecycle::IN=>Some(format!("承压 {}s · 正面接火 / 主炮停火",read::fixed(life.active_timer,1))),lifecycle::ACTIVE=>Some(format!("反击 {}s · 无盾速射",read::fixed(life.active_timer,1))),lifecycle::OUT=>Some("恢复 · 可右键开盾 / 装填减速".into()),_=>None},
        e::Kind::GravityWell|e::Kind::GravityBattleWell|e::Kind::GravityOther=>{let g=gravity.ok_or(8u32)?;match g.kind{
            g::Kind::Well=>g.field.as_ref().filter(|_|life.state==lifecycle::ACTIVE).map(|_|format!("引力井 · 固定场 / 再按收回 · {}s",read::fixed(life.active_timer,1))),g::Kind::Repulsor|g::Kind::BattleRepulsor=>g.field.as_ref().map(|_|"排斥波扩张 · 每对象一次冲量".into()),
            g::Kind::Maneuver=>g.maneuver.map(|_|"惯性折转 · 不加速 / 舰首独立".into()),g::Kind::Release=>g.field.as_ref().map(|_|"远端排斥 · 锚已释放".into()),
            g::Kind::Collapse=>g.field.as_ref().map(|_|if life.state==lifecycle::IN{"潮汐收缩 · 0.45秒预警"}else{"潮汐崩解 · 单次命中"}.into()),
            g::Kind::BattleWell=>g.field.as_ref().map(|f|if f.kind==g::FieldKind::Collapse{if life.state==lifecycle::IN{"自动坍缩预警"}else{"到期潮汐爆"}.into()}else{format!("{}区域 · {} · 总余{}s",if f.polarity==Some(-1){"排斥"}else{"吸引"},if g.held{"操纵中".into()}else if f.cursor==Some(true){format!("驻留 {}s",read::fixed(f.linger.unwrap_or(0.0),1))}else{"自主场".into()},read::fixed(life.active_timer.max(0.0),1))}),
            g::Kind::Polarity=>{passive=Some(format!("极性 · {}",if g.polarity==Some(-1){"排斥"}else{"吸引"}));None},g::Kind::Push=>{if life.state==lifecycle::IDLE{passive=Some("按住右键 · 定向推送".into());}if g.held{Some(g.push.as_ref().map_or("对准实体推送",|p|p.status.as_str()).into())}else{None}}}},
        e::Kind::BurnDrive=>if life.active{Some(format!("推进中 · 航速 +{}",crate::gravity_owner::number_key(((if life.state==lifecycle::OUT{0.0}else{200.0*life.effect})+0.5).floor())))}else{None},
        e::Kind::AmmoFeed=>if life.active{Some(format!("实弹射速 +{}% · 载荷消耗 -50%",crate::gravity_owner::number_key((life.effect*100.0+0.5).floor())))}else{None},
        e::Kind::HighEnergyFocus=>if life.active{Some(format!("能量伤害 +{}%",crate::gravity_owner::number_key((life.effect*50.0+0.5).floor())))}else{None},
        e::Kind::ManeuveringJets=>if life.active{Some(format!("机动增强 · 加减速 +{}%",crate::gravity_owner::number_key(((if life.state==lifecycle::OUT{life.out_level}else{life.effect})*200.0+0.5).floor())))}else{None},
        e::Kind::None|e::Kind::FortressShield|e::Kind::PlasmaJets=>None};Ok((text,passive))}
pub fn words(meta:&Owned,b:&[Body],world:&world_owner::Owned,ordnance:&Ordnance,specs:&BTreeMap<u32,Spec>)->Result<Vec<f64>,u32>{
    words_observed(meta,world,ordnance,std::rc::Rc::new(so::PublicationObservation::new(b,specs)))}
pub(crate) fn words_observed<'a>(meta:&Owned,world:&'a world_owner::Owned,ordnance:&Ordnance,observation:std::rc::Rc<so::PublicationObservation<'a>>)->Result<Vec<f64>,u32>{
    let b=observation.bodies();let specs=observation.specs();meta.validate(b)?;let reader=Reader::publication(world,observation);reader.active()?;let mut out=vec![1.0,0.0];let mut n=0;
    for body in b{let s=body.ship.as_ref().ok_or(8u32)?;let own=s.world.as_ref().ok_or(8u32)?;let gravity=world.gravity.as_ref().and_then(|g|g.owner.ships.iter().find(|m|m.identity==read::id(body.handle)));
        for (i,life)in s.systems.iter().enumerate(){let m=own.metas.get(&life.id).ok_or(8u32)?;let g=gravity.and_then(|m|m.systems.iter().find(|m|m.id==life.id));let reason=reader.system_reason_at_barrier(body.handle,life.id)?;let(status,passive)=status(meta,&reader,body.handle,life,m.kind,g)?;let available=specs.get(&life.spec).ok_or(8u32)?.flags&lifecycle::AVAILABLE!=0;let mut v=vec![body.id as f64,life.id as f64,bool_word(life.active),bool_word(available)];opt_string(&mut v,reason.as_deref());opt_string(&mut v,status.as_deref());opt_string(&mut v,passive.as_deref());
            let fortress=s.systems[i..].iter().map(|s|if matches!(own.metas[&s.id].kind,e::Kind::ArkBarrier|e::Kind::Zhefeng|e::Kind::FortressShield){s.effect}else{0.0}).fold(0.0,f64::max);v.extend([fortress,0.0,bool_word(g.is_some_and(|g|g.held))]);optional(&mut v,g.and_then(|g|g.polarity).map(|p|p as f64));
            v.push(bool_word(g.is_some_and(|g|g.field.is_some())));if let Some(f)=g.and_then(|g|g.field.as_ref()){field(&mut v,f,meta,world,ordnance)?;}
            v.push(bool_word(g.is_some_and(|g|g.push.is_some())));if let Some(p)=g.and_then(|g|g.push.as_ref()){opt_target(&mut v,p.target,meta,world,ordnance)?;v.extend(p.position);v.push(p.radius);v.extend(p.direction);v.push(p.age);string(&mut v,&p.status);}
            v.push(bool_word(g.is_some_and(|g|g.maneuver.is_some())));if let Some(m)=g.and_then(|g|g.maneuver){v.extend([m.target_angle,m.age,m.turn_remaining]);}
            v.push(bool_word(m.jump.visual.is_some()));if let Some(j)=m.jump.visual{v.push(j.serial);v.extend(j.destination);v.push(j.destination_facing);v.push(bool_word(j.origin.is_some()));if let Some(o)=j.origin{v.extend(o);}optional(&mut v,j.origin_facing);}record(&mut out,&mut n,1,v);
        }
        for mount in &s.weapons.as_ref().ok_or(8u32)?.mounts{let dynamic=gravity.and_then(|g|g.mounts.iter().find(|m|m.id==mount.data[0]as u32));let mut v=vec![body.id as f64,mount.data[0],0.0];v.push(bool_word(dynamic.is_some_and(|m|m.tractor.is_some())));if let Some(t)=dynamic.and_then(|m|m.tractor.as_ref()){v.push(match t.phase{g::Phase::Idle=>0.0,g::Phase::Capture=>1.0,g::Phase::Hold=>2.0});optional(&mut v,t.polarity.map(|p|p as f64));opt_target(&mut v,t.target,meta,world,ordnance)?;v.extend([t.capture,t.age,t.anchor[0],t.anchor[1],t.contact[0],t.contact[1]]);optional(&mut v,t.radius);v.push(bool_word(t.wait_release));string(&mut v,&t.status);optional(&mut v,t.damage_clock);}
            v.push(bool_word(dynamic.is_some_and(|m|m.deflection.is_some())));if let Some((p,age))=dynamic.and_then(|m|m.deflection){v.extend(p);v.push(age);}record(&mut out,&mut n,2,v);}
        // Current registered packs never call a presentation pose/angle setter.
        let mut v=vec![body.id as f64,0.0,1.0];v.extend(own.camera);record(&mut out,&mut n,3,v);
    }if out.len()>8_000_000||out.iter().any(|v|!v.is_finite()){return Err(7);}out[1]=n as f64;Ok(out)
}
